                source = mod.get("source")
                if not source or not (source.endswith(".ts") or source.endswith(".tsx")):
                    continue
                deps = mod.get("dependencies") or []
                for d in deps:
                    target = d.get("resolved") or d.get("module") or d.get("dependency")
                    if not target:
