{"output":"import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios'

// Detect debug from query param once at boot
const isDebug = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('debug') === '1'

// Create axios instance with default config
const apiClient: AxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || '/api/v1',
  timeout: 60000,
  withCredentials: true,
  headers: {
    'Content-Type': 'application/json',
  },
})

// Request interceptor to add X-Request-ID
apiClient.interceptors.request.use(
  (config) => {
    // Generate or get existing correlation ID
    const correlationId = localStorage.getItem('correlationId') || crypto.randomUUID()
    localStorage.setItem('correlationId', correlationId)

    // Add X-Request-ID header
    if (config.headers) {
      config.headers['X-Request-ID'] = correlationId
    }

    if (isDebug) {
      // Lightweight request log
      try {
        // eslint-disable-next-line no-console
        console.info('[FF/API] →', config.method?.toUpperCase(), config.baseURL + (config.url || ''))
      } catch {}
    }
    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

// Response interceptor to handle errors
apiClient.interceptors.response.use(
  (response: AxiosResponse) => {
    if (isDebug) {
      try {
        // eslint-disable-next-line no-console
        console.info('[FF/API] ←', response.status, response.config.baseURL + (response.config.url || ''))
      } catch {}
    }
    return response
  },
  (error) => {
    // Log error
    console.error('API Error:', error)
    try {
      const headers: any = (error?.config?.headers || {})
      const suppressHeader = Boolean(headers['X-Suppress-Alert'] || headers['x-suppress-alert'])
      const urlStr = ((error?.config?.baseURL || '') + (error?.config?.url || '')).toLowerCase()
      const suppressByUrl = urlStr.includes('/admin/tokens/summary') || urlStr.includes('/logs/errors')
      const suppress = suppressHeader || suppressByUrl
      if (!suppress && typeof window !== 'undefined') {
        const status = error?.response?.status
        const url = (error?.config?.baseURL || '') + (error?.config?.url || '')
        const message = error?.message || 'API request failed'
        window.dispatchEvent(new CustomEvent('ff-api-error', { detail: { status, url, message } }))
      }
    } catch {}

    // Return error for handling in components
    return Promise.reject(error)
  }
)

// Generic API call function
export const apiCall = async <T>(
  config: AxiosRequestConfig
): Promise<AxiosResponse<T>> => {
  return await apiClient(config)
}

// Helper functions for common HTTP methods
export const get = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'GET', url })
}

export const post = async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'POST', url, data })
}

export const put = async <T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'PUT', url, data })
}

export const del = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  return await apiCall<T>({ ...config, method: 'DELETE', url })
}

export default apiClient

// Absolute GET (bypass baseURL), useful for non-/api/v1 endpoints like /health/ready
export const getAbsolute = async <T>(url: string, config?: AxiosRequestConfig): Promise<AxiosResponse<T>> => {
  const client = axios.create({ 
    timeout: 60000, 
    withCredentials: true,
    headers: { 'Content-Type': 'application/json' } 
  })
  return await client.get<T>(url, config)
}
