interface Task {
  id: number
  feature_id: number
  role: string
  status: string
  attempts: number
  scheduled_at?: string | number
  started_at?: string | number
}

interface FeatureMeta { id: number; title?: string }
interface LogEntry { ts: string | number; level: string; component: string; event: string; kv?: any }

const DEFAULT_ROLES = ['Architect','Dev','QA','Scribe','Maintainer']

const TaskDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>()
  const [task, setTask] = useState<Task | null>(null)
  const [feature, setFeature] = useState<FeatureMeta | null>(null)
  const [logsAll, setLogsAll] = useState<LogEntry[]>([])
  const [tab, setTab] = useState<'milestones'|'errors'|'all'>('milestones')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchData = async () => {
    if (!id) return
    try {
      setLoading(true)
      // Основной запрос
      try {
        const resp = await get<Task>(`/orchestrator/tasks/${id}`)
        setTask(resp.data)
      } catch (e) {
        // fallback через список
        const resp = await get<Task[]>(`/orchestrator/tasks?id=${id}`)
        setTask(Array.isArray(resp.data) ? resp.data[0] : null)
      }
      if (task?.feature_id) {
        try {
          const f = await get<FeatureMeta>(`/orchestrator/features/${task.feature_id}`)
          setFeature(f.data)
        } catch {}
      }
      try {
        const logs = await get<LogEntry[]>(`/logs/tail?limit=200&task_id=${id}`)
        setLogsAll(logs.data || [])
      } catch { setLogsAll([]) }
      setError(null)
    } catch (e) {
      // eslint-disable-next-line no-console
      console.error('TaskDetail: fetch error', e)
      setError('Failed to fetch data')
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { fetchData() }, [id])

  const roles = DEFAULT_ROLES
  const currentRole = task?.role
  const mermaidChart = useMemo(() => {
    const nodes = roles.map(r => r).join(' --> ')
    const clsName = (currentRole && roles.includes(currentRole)) ? currentRole : ''
    const classDef = 'classDef current fill:#93c5fd,stroke:#1d4ed8,stroke-width:2px,color:#111;'
    const classApply = clsName ? `class ${clsName} current;` : ''
    const labels = roles.map(r => `${r}[${formatRole(r)}]`).join('\n')
    return `graph LR\n${labels}\n${nodes}\n${classDef}\n${classApply}`
  }, [roles, currentRole])

  const milestoneEvents = new Set(['job_started','job_finished','task_started','task_finished'])
  const logsMilestones = logsAll.filter(l => milestoneEvents.has((l.event||'').toString()))
  const logsErrors = logsAll.filter(l => ['ERROR','CRITICAL'].includes((l.level||'').toUpperCase()))

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
      </div>
    )
  }
  if (error || !task) {
    return (
      <div className="space-y-6">
        <Button variant="outline" size="sm" asChild>
          <Link to="/tasks"><ArrowLeft className="h-4 w-4 mr-2" />Назад к задачам</Link>
        </Button>
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded">{error || 'Задача не найдена'}</div>
      </div>
    )
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Задача #{task.id} • {formatRole(task.role)}</h1>
          <p className="text-sm text-gray-500">Фича #{task.feature_id} {feature?.title ? `• ${feature.title}` : ''}</p>
        </div>
        <div className="flex items-center gap-2">
          <Badge>{task.status}</Badge>
          <Button asChild variant="outline"><Link to={`/features/${task.feature_id}`}>К фиче</Link></Button>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center"><Activity className="h-5 w-5 mr-2"/>Граф G1</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="mb-2 text-sm">Текущий шаг: {formatRole(task.role)}</div>
          <Mermaid chart={mermaidChart} />
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center"><FileText className="h-5 w-5 mr-2"/>Сведения</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
            <div><span className="text-gray-500">Роль:</span> {formatRole(task.role)}</div>
            <div><span className="text-gray-500">Попытки:</span> {task.attempts}</div>
            <div><span className="text-gray-500">Запланировано:</span> {task.scheduled_at ? formatDate(task.scheduled_at) : '—'}</div>
            <div><span className="text-gray-500">Начато:</span> {task.started_at ? formatDate(task.started_at) : '—'}</div>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Логи задачи</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="mb-3 flex gap-2 text-sm">
            <Button size="sm" variant={tab==='milestones'?'default':'outline'} onClick={()=>setTab('milestones')}>Основные вехи</Button>
            <Button size="sm" variant={tab==='errors'?'default':'outline'} onClick={()=>setTab('errors')}>Ошибки</Button>
            <Button size="sm" variant={tab==='all'?'default':'outline'} onClick={()=>setTab('all')}>Все логи</Button>
          </div>
          {tab==='milestones' && (
            logsMilestones.length === 0 ? <div className="text-sm text-gray-500">Нет записей</div> : (
              <ul className="text-sm space-y-1">
                {logsMilestones.map((l, i) => (
                  <li key={i}>[{formatDate(l.ts)}] {l.level} {l.component}: {l.event}</li>
                ))}
              </ul>
            )
          )}
          {tab==='errors' && (
            logsErrors.length === 0 ? <div className="text-sm text-gray-500">Нет ошибок</div> : (
              <ul className="text-sm space-y-1">
                {logsErrors.map((l, i) => (
                  <li key={i} className="text-red-600 flex items-center"><AlertTriangle className="h-4 w-4 mr-1"/>[{formatDate(l.ts)}] {l.component}: {l.event}</li>
                ))}
              </ul>
            )
          )}
          {tab==='all' && (
            logsAll.length === 0 ? <div className="text-sm text-gray-500">Нет логов</div> : (
              <ul className="text-sm space-y-1">
                {logsAll.map((l, i) => (
                  <li key={i}>[{formatDate(l.ts)}] {l.level} {l.component}: {l.event}</li>
                ))}
              </ul>
            )
          )}
          <div className="mt-3 flex justify-end"><Button onClick={fetchData}><RefreshCw className="h-4 w-4 mr-2"/>Обновить</Button></div>
        </CardContent>
      </Card>
    </div>
  )
}

export default TaskDetail
