export class SSEClient {
  private eventSource: EventSource | null = null
  private listeners: Map<string, ((data: any) => void)[]> = new Map()
  private reconnectInterval: number | null = null
  private readonly BASE_URL: string

  constructor(baseUrl?: string) {
    this.BASE_URL = baseUrl || import.meta.env.VITE_API_BASE_URL || '/api/v1'
  }

  // Connect to SSE endpoint
  public connect(endpoint: string): void {
    if (this.eventSource) {
      this.disconnect()
    }
    // Сбрасываем слушателей, чтобы избежать дубликатов при повторных заходах
    this.listeners.clear()

    const url = `${this.BASE_URL}${endpoint}`
    // Включаем отправку кредов для BasicAuth
    // @ts-ignore: EventSourceInit withCredentials is supported by browsers
    this.eventSource = new EventSource(url, { withCredentials: true })

    // Add event listeners
    this.eventSource.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit(event.type, data)
      } catch (error) {
        console.error('Error parsing SSE message:', error)
      }
    }

    this.eventSource.onerror = (error) => {
      console.error('SSE Error:', error)
      try {
        if (typeof window !== 'undefined') {
          window.dispatchEvent(new CustomEvent('ff-sse-error', { detail: { error } }))
        }
      } catch {}
      this.handleReconnect()
    }

    // Listen for specific event types
    this.eventSource.addEventListener('job_started', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('job_started', data)
      } catch (error) {
        console.error('Error parsing job_started event:', error)
      }
    })

    this.eventSource.addEventListener('job_finished', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('job_finished', data)
      } catch (error) {
        console.error('Error parsing job_finished event:', error)
      }
    })

    this.eventSource.addEventListener('error', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('error', data)
      } catch (error) {
        console.error('Error parsing error event:', error)
      }
    })

    this.eventSource.addEventListener('index_updated', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('index_updated', data)
      } catch (error) {
        console.error('Error parsing index_updated event:', error)
      }
    })

    this.eventSource.addEventListener('doc_updated', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('doc_updated', data)
      } catch (error) {
        console.error('Error parsing doc_updated event:', error)
      }
    })

    this.eventSource.addEventListener('llm_call_end', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('llm_call_end', data)
      } catch (error) {
        console.error('Error parsing llm_call_end event:', error)
      }
    })
    // Generic log event (если бэкенд шлёт сырые логи)
    this.eventSource.addEventListener('log', (event) => {
      try {
        const data = JSON.parse(event.data)
        this.emit('log', data)
      } catch (error) {
        console.error('Error parsing log event:', error)
      }
    })
  }

  // Disconnect from SSE endpoint
  public disconnect(): void {
    if (this.eventSource) {
      this.eventSource.close()
      this.eventSource = null
    }

    if (this.reconnectInterval) {
      clearInterval(this.reconnectInterval)
      this.reconnectInterval = null
    }
  }

  // Add event listener
  public on(event: string, callback: (data: any) => void): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, [])
    }

    this.listeners.get(event)?.push(callback)
  }

  // Remove event listener
  public off(event: string, callback: (data: any) => void): void {
    const callbacks = this.listeners.get(event)
    if (callbacks) {
      const index = callbacks.indexOf(callback)
      if (index !== -1) {
        callbacks.splice(index, 1)
      }
    }
  }

  // Emit event to all listeners
  private emit(event: string, data: any): void {
    const callbacks = this.listeners.get(event)
    if (callbacks) {
      callbacks.forEach((callback) => {
        try {
          callback(data)
        } catch (error) {
          console.error(`Error in ${event} listener:`, error)
        }
      })
    }
  }

  // Handle reconnection
  private handleReconnect(): void {
    if (!this.reconnectInterval) {
      this.reconnectInterval = window.setInterval(() => {
        if (this.eventSource?.readyState === EventSource.CLOSED) {
          // Attempt to reconnect
          // Note: In a real implementation, we would need to know the endpoint to reconnect to
          console.log('Attempting to reconnect to SSE...')
        }
      }, 5000)
    }
  }
}

